// === Tab: mySketch ===
// Attractor_7.1

let X ; let Y ; let dX ; let dY ; let Q ; let Qmax ; long T ;
let PX ; let PY ; let Cmax ; let C ; let KX ; let KY ;
let R = 0.005 ; let G = 0.005 ; let B = 0.005 ;

function setup(){
  createCanvas(900, 380) ; noSmooth() ; background(0) ; 
}//setup()

function draw(){
  for ( Q = 0 ; Q < Qmax ; Q++ ){
    KX = (X-450)/50 ; KY = (Y-200)/50 ;
    dY = sin(KX) - (0.1*KX) + (1.75*sin(C)) - (0.0001*KY) ;
    dX = KY ;
    X = X + (dX*10) ; Y = Y + (dY*10) ; C = C + 0.01 ; 
    if ( C >= Cmax ){
      stroke(125*sin(Y*R)+125,125*sin(Y*G)+125,125*sin(Y*B)+125) ; point(PX,PY) ; 
      C = 0 ; PX = PX + 1 ; 
      if ( PX >= 900 ){ PX = 0 ; PY = PY + 1 ; }
      if ( PY >= 380 ){ PY = 0 ; Cmax = Cmax + 0.2 ; }
      X = PX ; Y = PY ;
    }
  }
  if ( millis() - T > 20 && Qmax > 1000 ){ Qmax = Qmax - 100 ; }else{ Qmax = Qmax + 100 ; }
  T = millis() ; 
} // draw()

function mousePressed(){ R = random(0,0.01) ; G = random(0,0.01) ; B = random(0,0.01) ;  }

